// Velociraptor docs: Pagefind search modal (replaces Blowfish's Fuse.js search).
// The modal markup lives in layouts/partials/search.html; results are rendered
// by the Pagefind UI into #pagefind-ui. Pagefind assets are generated by
// `pagefind --site public` at build time (see package.json / Makefile).
(function () {
  "use strict";

  var showButton = document.getElementById("search-button");
  var showButtonMobile = document.getElementById("search-button-mobile");
  var hideButton = document.getElementById("close-search-button");
  var wrapper = document.getElementById("search-wrapper");
  var modal = document.getElementById("search-modal");
  var shortcutHint = document.getElementById("search-shortcut-hint");

  var searchVisible = false;
  var previouslyFocused = null;
  var pagefindUI = null;
  var pagefindLoaded = false;

  if (shortcutHint && !/Mac|iPhone|iPad/.test(navigator.platform)) {
    shortcutHint.textContent = "Ctrl K";
  }

  function loadPagefind() {
    if (pagefindLoaded) {
      return Promise.resolve();
    }
    pagefindLoaded = true;
    return new Promise(function (resolve, reject) {
      var css = document.createElement("link");
      css.rel = "stylesheet";
      css.href = "/pagefind/pagefind-ui.css";
      document.head.appendChild(css);

      var script = document.createElement("script");
      script.src = "/pagefind/pagefind-ui.js";
      script.onload = resolve;
      script.onerror = function () {
        pagefindLoaded = false;
        reject(new Error("pagefind-ui.js failed to load"));
      };
      document.head.appendChild(script);
    });
  }

  function displaySearch() {
    if (searchVisible) {
      return;
    }
    searchVisible = true;
    previouslyFocused = document.activeElement;
    wrapper.classList.remove("invisible");
    loadPagefind()
      .then(function () {
        if (!pagefindUI) {
          pagefindUI = new PagefindUI({
            element: "#pagefind-ui",
            showSubResults: true,
            showImages: false,
            highlightParam: "q"
          });
        }
        var input = document.querySelector("#pagefind-ui input");
        if (input) {
          setTimeout(function () {
            input.focus();
          }, 60);
        }
      })
      .catch(function () {});
  }

  function hideSearch() {
    if (!searchVisible) {
      return;
    }
    searchVisible = false;
    wrapper.classList.add("invisible");
    if (previouslyFocused && previouslyFocused.focus) {
      previouslyFocused.focus();
    }
  }

  if (showButton) {
    showButton.addEventListener("click", displaySearch);
  }
  if (showButtonMobile) {
    showButtonMobile.addEventListener("click", displaySearch);
  }
  if (hideButton) {
    hideButton.addEventListener("click", hideSearch);
  }
  if (wrapper) {
    wrapper.addEventListener("click", hideSearch);
  }
  if (modal) {
    modal.addEventListener("click", function (event) {
      event.stopPropagation();
      event.stopImmediatePropagation();
      return false;
    });
  }

  document.addEventListener("keydown", function (event) {
    // Forward slash opens search unless we are already typing somewhere.
    if (event.key === "/") {
      var active = document.activeElement;
      var tag = active ? active.tagName : null;
      var isInputField =
        tag === "INPUT" ||
        tag === "TEXTAREA" ||
        (active && active.isContentEditable);

      if (!searchVisible && !isInputField) {
        event.preventDefault();
        displaySearch();
      }
    }

    // Cmd+K (macOS) / Ctrl+K toggles the search modal.
    if (
      (event.key && event.key.toLowerCase() === "k") &&
      (event.metaKey || event.ctrlKey)
    ) {
      event.preventDefault();
      if (searchVisible) {
        hideSearch();
      } else {
        displaySearch();
      }
    }

    // Esc closes the search modal.
    if (event.key === "Escape") {
      hideSearch();
    }
  });
})();